import { TestBed } from '@angular/core/testing';

import { E2eCryptoService } from './e2e-crypto.service';

describe('E2eCryptoService（端到端加密闭环）', () => {
  let svc: E2eCryptoService;

  beforeEach(() => {
    TestBed.configureTestingModule({});
    svc = TestBed.inject(E2eCryptoService);
  });

  it('generateSalt 返回 16 字节 base64', () => {
    const salt = svc.generateSalt();
    expect(salt.length).toBeGreaterThan(16);
    expect(atob(salt).length).toBe(16);
  });

  it('encryptFile → openEnvelope → decryptFile 明文往返一致', async () => {
    const plain = '机密内容：Hello RustFS 端到端加密 🚀';
    const file = new File([new TextEncoder().encode(plain)], 'secret.txt', { type: 'text/plain' });
    const passphrase = 'correct horse battery staple';

    const { cipher, envelope } = await svc.encryptFile(file, passphrase);
    expect(envelope.v).toBe(1);
    expect(envelope.kdf.algo).toBe('PBKDF2');
    expect(cipher.size).toBeGreaterThan(plain.length);

    const dek = await svc.openEnvelope(passphrase, envelope);
    const decrypted = await svc.decryptFile(cipher, dek);
    expect(await decrypted.text()).toBe(plain);
  });

  it('口令错误时 openEnvelope 抛异常（GCM 认证失败）', async () => {
    const file = new File([new TextEncoder().encode('data')], 'a.txt', { type: 'text/plain' });
    const { envelope } = await svc.encryptFile(file, 'right-password');

    await expectAsync(svc.openEnvelope('wrong-password', envelope)).toBeRejected();
  });

  it('密文被篡改时 decryptFile 抛异常', async () => {
    const file = new File([new TextEncoder().encode('tamper me')], 'a.txt', { type: 'text/plain' });
    const passphrase = 'pw';
    const { cipher, envelope } = await svc.encryptFile(file, passphrase);
    const dek = await svc.openEnvelope(passphrase, envelope);

    // 翻转密文第 20 字节（越过 12 字节 IV，落在 GCM tag 区）
    const buf = new Uint8Array(await cipher.arrayBuffer());
    buf[20] ^= 0xff;
    const tampered = new Blob([buf], { type: 'application/octet-stream' });

    await expectAsync(svc.decryptFile(tampered, dek)).toBeRejected();
  });

  it('分享重包裹闭环：属主信封 → 分享密码信封 → 接收方解密一致', async () => {
    const plain = '分享给同事的加密文档';
    const file = new File([new TextEncoder().encode(plain)], 'share.md', { type: 'text/markdown' });
    const ownerPass = 'owner-pass';
    const sharePass = 'share-pass';

    const { cipher, envelope: ownerEnv } = await svc.encryptFile(file, ownerPass);
    const shareEnv = await svc.rewrapDataKeyToShare(ownerEnv, ownerPass, sharePass);

    const decrypted = await svc.decryptSharedContent(cipher, shareEnv, sharePass);
    expect(await decrypted.text()).toBe(plain);
  });

  it('分享密码错误时解密失败', async () => {
    const file = new File([new TextEncoder().encode('x')], 'x.txt', { type: 'text/plain' });
    const { cipher, envelope: ownerEnv } = await svc.encryptFile(file, 'owner-pass');
    const shareEnv = await svc.rewrapDataKeyToShare(ownerEnv, 'owner-pass', 'share-pass');

    await expectAsync(svc.decryptSharedContent(cipher, shareEnv, 'bad-pass')).toBeRejected();
  });

  it('parseEnvelope 校验：合法通过、非法抛错', () => {
    const salt = svc.generateSalt();
    const env: import('./e2e-crypto.service').Envelope = {
      v: 1,
      kdf: { algo: 'PBKDF2', hash: 'SHA-256', iterations: 1000, salt },
      wrapped: 'AAA=',
    };
    expect(svc.parseEnvelope(JSON.stringify(env))).toEqual(env);

    expect(() => svc.parseEnvelope('not-json')).toThrow();
    expect(() => svc.parseEnvelope(JSON.stringify({ v: 2, wrapped: 'x' }))).toThrow();
    expect(() => svc.parseEnvelope(JSON.stringify({ v: 1 }))).toThrow();
  });
});
