/**
 * E2E（零知识）加密 SDK —— 纯 WebCrypto 实现，无第三方密码学依赖。
 *
 * 方案（与后端 `EncryptionMode.EndToEnd` 语义对齐）：
 * - 每文件生成随机数据密钥 DEK（AES-256-GCM，256 位）。
 * - DEK 用「主密钥 KEK」信封加密后随元数据一并存储（后端不解析、不透传）。
 * - KEK 由用户加密口令经 PBKDF2-SHA256 派生（口令不落盘，仅保存公开盐值 salt）。
 * - 文件密文经现有「预签名 PUT 直传」上传；内容哈希为密文哈希，仅作完整性校验。
 *
 * 密文格式（自包含）：`[nonce(12) | AES-256-GCM(ciphertext + authTag)]`。
 * 信封格式（JSON 字符串，作为 EncryptedDataKey 上报后端）：见 {@link Envelope}。
 *
 * 说明：WebCrypto AES-GCM 需一次性读入整文件（arrayBuffer）；超大文件的流式分块
 *（手动 counter 管理 nonce）属后续优化，当前以简洁正确为首要。
 */
import { Injectable } from '@angular/core';

const PBKDF2_ITERATIONS = 210_000;
const SALT_BYTES = 16;
const GCM_IV_BYTES = 12;
const KEY_BYTES = 32;

/** 主密钥（KEK）派生的公开参数：盐值 base64 + 迭代次数（供下载时还原同一 KEK）。 */
export interface KdfParams {
  algo: 'PBKDF2';
  hash: 'SHA-256';
  iterations: number;
  salt: string;
}

/** 上报后端的信封：自描述的 KDF 参数 + 被封装（iv||cipher，base64）的 DEK。 */
export interface Envelope {
  v: 1;
  kdf: KdfParams;
  /** AES-GCM(KEK, DEK) 的 iv||密文（base64）。 */
  wrapped: string;
}

/** 加密完成结果：密文 Blob + 密文内容 SHA-256（hex）+ 信封（待上报为 EncryptedDataKey）。 */
export interface EncryptResult {
  cipher: Blob;
  contentSha256: string;
  envelope: Envelope;
}

function subtle(): SubtleCrypto {
  if (typeof crypto === 'undefined' || !crypto.subtle) {
    throw new Error('当前环境不支持 WebCrypto，无法使用端到端加密。请在 HTTPS 或 localhost 下使用。');
  }
  return crypto.subtle;
}

function randomBytes(n: number): Uint8Array<ArrayBuffer> {
  const buf = new Uint8Array(n);
  crypto.getRandomValues(buf);
  return buf;
}

function toB64(bytes: ArrayBuffer | Uint8Array): string {
  const u8 = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes);
  let bin = '';
  for (const byte of u8) bin += String.fromCharCode(byte);
  return btoa(bin);
}

function fromB64(b64: string): Uint8Array<ArrayBuffer> {
  const bin = atob(b64);
  const u8 = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i += 1) u8[i] = bin.charCodeAt(i);
  return u8;
}

/** 归一化为 ArrayBuffer（TS6 严格 DOM 类型：BufferSource 要求 ArrayBuffer-backed）。 */
function toBuf(data: ArrayBuffer | Uint8Array): ArrayBuffer {
  if (data instanceof ArrayBuffer) return data;
  const out = new ArrayBuffer(data.byteLength);
  new Uint8Array(out).set(data);
  return out;
}

/** 计算字节串 SHA-256（hex）—— WebCrypto 原生实现，无第三方依赖。 */
async function sha256Bytes(bytes: Uint8Array): Promise<string> {
  const digest = await subtle().digest('SHA-256', toBuf(bytes));
  return Array.from(new Uint8Array(digest))
    .map((b) => b.toString(16).padStart(2, '0'))
    .join('');
}

@Injectable({ providedIn: 'root' })
export class E2eCryptoService {
  /** 生成随机 KDF 盐值（base64）。盐值非保密，仅用于从同一口令派生固定 KEK。 */
  generateSalt(): string {
    return toB64(randomBytes(SALT_BYTES));
  }

  /** 默认 KDF 参数（新文件首次加密时生成）。 */
  createKdfParams(salt: string): KdfParams {
    return { algo: 'PBKDF2', hash: 'SHA-256', iterations: PBKDF2_ITERATIONS, salt };
  }

  /** 由口令派生主密钥 KEK（AES-GCM 256 位，不可导出，防止被脚本窃取）。 */
  async deriveMasterKey(passphrase: string, params: KdfParams): Promise<CryptoKey> {
    const base = await subtle().importKey(
      'raw',
      new TextEncoder().encode(passphrase),
      'PBKDF2',
      false,
      ['deriveKey'],
    );
    return subtle().deriveKey(
      { name: 'PBKDF2', salt: fromB64(params.salt), iterations: params.iterations, hash: params.hash },
      base,
      { name: 'AES-GCM', length: KEY_BYTES * 8 },
      false,
      ['encrypt', 'decrypt'],
    );
  }

  /** 生成每文件的随机数据密钥 DEK（AES-256-GCM，可导出以便信封封装）。 */
  async generateDataKey(): Promise<CryptoKey> {
    return subtle().generateKey({ name: 'AES-GCM', length: KEY_BYTES * 8 }, true, ['encrypt', 'decrypt']);
  }

  /** 信封封装：用 KEK 加密 DEK，返回 `iv(12)||密文` 的 base64。 */
  async wrapDataKey(kek: CryptoKey, dek: CryptoKey): Promise<string> {
    const raw = await subtle().exportKey('raw', dek);
    const iv = randomBytes(GCM_IV_BYTES);
    const enc = await subtle().encrypt({ name: 'AES-GCM', iv: toBuf(iv) }, kek, raw);
    const out = new Uint8Array(iv.length + enc.byteLength);
    out.set(iv, 0);
    out.set(new Uint8Array(enc), iv.length);
    return toB64(out);
  }

  /** 还原 DEK：按信封（含 KDF 参数 + wrapped）解封装出数据密钥。口令错误或信封被篡改时抛异常。 */
  async openEnvelope(passphrase: string, envelope: Envelope): Promise<CryptoKey> {
    const kek = await this.deriveMasterKey(passphrase, envelope.kdf);
    const blob = fromB64(envelope.wrapped);
    const iv = blob.subarray(0, GCM_IV_BYTES);
    const data = blob.subarray(GCM_IV_BYTES);
    const raw = await subtle().decrypt({ name: 'AES-GCM', iv: toBuf(iv) }, kek, toBuf(data));
    return subtle().importKey('raw', raw, { name: 'AES-GCM' }, true, ['encrypt', 'decrypt']);
  }

  /**
   * 端到端加密一个文件：
   * 1) 生成随机 DEK；2) AES-256-GCM 加密整文件；3) 计算密文 SHA-256；
   * 4) 用口令派生的 KEK 信封封装 DEK，产出可上报的 {@link Envelope}。
   */
  async encryptFile(file: File, passphrase: string): Promise<EncryptResult> {
    const dek = await this.generateDataKey();
    const content = await file.arrayBuffer();

    const iv = randomBytes(GCM_IV_BYTES);
    const enc = await subtle().encrypt({ name: 'AES-GCM', iv: toBuf(iv) }, dek, content);
    const full = new Uint8Array(iv.length + enc.byteLength);
    full.set(iv, 0);
    full.set(new Uint8Array(enc), iv.length);

    const salt = this.generateSalt();
    const kek = await this.deriveMasterKey(passphrase, this.createKdfParams(salt));
    const wrapped = await this.wrapDataKey(kek, dek);

    return {
      cipher: new Blob([full], { type: 'application/octet-stream' }),
      contentSha256: await sha256Bytes(full),
      envelope: { v: 1, kdf: this.createKdfParams(salt), wrapped },
    };
  }

  /**
   * 用 DEK 解密密文 Blob（`[iv | ciphertext+tag]`）返回明文内容。
   * GCM 认证标签自动校验密文完整性；口令错 / 密文被改 / 数据损坏均抛异常。
   */
  async decryptFile(cipher: Blob, dek: CryptoKey): Promise<Blob> {
    const buf = new Uint8Array(await cipher.arrayBuffer());
    const iv = buf.subarray(0, GCM_IV_BYTES);
    const data = buf.subarray(GCM_IV_BYTES);
    const raw = await subtle().decrypt({ name: 'AES-GCM', iv: toBuf(iv) }, dek, toBuf(data));
    return new Blob([raw]);
  }

  /** 解析由 {@link encryptFile} 生成、作为 EncryptedDataKey 上报的 JSON 信封。 */
  parseEnvelope(raw: string): Envelope {
    const parsed: unknown = JSON.parse(raw);
    if (
      typeof parsed !== 'object' ||
      parsed === null ||
      (parsed as Envelope).v !== 1 ||
      typeof (parsed as Envelope).wrapped !== 'string'
    ) {
      throw new Error('信封格式不受支持。');
    }
    return parsed as Envelope;
  }

  /**
   * 为分享「重包裹」DEK：用属主口令解出文件 DEK，再改用「分享访问密码」派生的 KEK 重新信封封装。
   * 服务端仅存此接收方信封，不掉落属主口令或 DEK；接收方持访问密码即可解出 DEK 解密。
   */
  async rewrapDataKeyToShare(
    ownerEnvelope: Envelope,
    ownerPassphrase: string,
    sharePassword: string,
  ): Promise<Envelope> {
    const dek = await this.openEnvelope(ownerPassphrase, ownerEnvelope);
    const salt = this.generateSalt();
    const kek = await this.deriveMasterKey(sharePassword, this.createKdfParams(salt));
    const wrapped = await this.wrapDataKey(kek, dek);
    return { v: 1, kdf: this.createKdfParams(salt), wrapped };
  }

  /**
   * 接收方解密分享的 E2E 文件：用分享访问密码解开接收方信封还原 DEK，再解密密文内容。
   * 访问密码错误 / 信封被篡改时抛异常。
   */
  async decryptSharedContent(cipher: Blob, shareEnvelope: Envelope, sharePassword: string): Promise<Blob> {
    const dek = await this.openEnvelope(sharePassword, shareEnvelope);
    return this.decryptFile(cipher, dek);
  }
}
